			assertMapSize("TripleStore", triples, SHACL_TRIPLE_MAP_SIZE_BYTES);
			System.out.printf(Locale.ROOT,
					"SHACL LMDB map proof: values capacity=%d high-water=%d; triples capacity=%d high-water=%d; "
							+ "resize counters value=%d triple=%d fallback=%d; growth episodes=%d%n",
					values.mapSizeBytes(), values.highWaterBytes(), triples.mapSizeBytes(), triples.highWaterBytes(),
					growth.valueStoreResizes(), growth.tripleStoreResizes(), growth.fallbackResizes(),
					growth.growthEpisodes());
